import sys

def solve(path: str) -> str:
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)
    simplified = '/' + '/'.join(stack)
    return simplified if simplified != '' else '/'

def solve(nums):
    # Find the first index from the right where nums[i] < nums[i+1]
    n = len(nums)
    arr = list(nums)  # copy to avoid mutating input
    i = n - 2
    while i >= 0 and arr[i] >= arr[i+1]:
        i -= 1
    if i == -1:
        return sorted(arr)
    # Find the smallest element greater than arr[i] to the right
    j = n - 1
    while arr[j] <= arr[i]:
        j -= 1
    arr[i], arr[j] = arr[j], arr[i]
    arr[i+1:] = reversed(arr[i+1:])
    return arr

