{"task_id": "T30", "code": "import sys

def solve(path: str) -> str:
    """Simplify a Unix-style absolute path.
    Resolve '.' and '..', collapse multiple slashes, and remove trailing slash.
    The root remains '/'.
    """
    # Trim whitespace and ensure it's a string
    if not isinstance(path, str):
        raise TypeError("Path must be a string")
    path = path.strip()
    # Split by '/' and process components
    components = path.split('/')
    stack = []
    for comp in components:
        if comp == '' or comp == '.':
            # Skip empty components (from //) and current directory
            continue
        if comp == '..':
            if stack:
                stack.pop()
            # If stack empty, stay at root (ignore further '..')
        else:
            stack.append(comp)
    # Build the canonical path
    canonical = '/' + '/'.join(stack)
    return canonical

if __name__ == "__main__":
    data = sys.stdin.read().strip()
    if data:
        print(solve(data))
"}

