{"task_id": "T21", "code": "def solve(weights, values, capacity):
    """0/1 knapsack returning the maximum total value fitting within capacity.
    Uses a 1‑D DP array when capacity is moderate; otherwise falls back to a
    dictionary‑based DP that tracks only reachable weight/value pairs to avoid
    huge memory usage.
    """
    if capacity <= 0 or not weights:
        return 0
    # If capacity is reasonable, use classic DP for speed.
    if capacity <= 200000:
        dp = [0] * (capacity + 1)
        for w, v in zip(weights, values):
            if w > capacity:
                continue
            for c in range(capacity, w - 1, -1):
                new_val = dp[c - w] + v
                if new_val > dp[c]:
                    dp[c] = new_val
        return dp[capacity]
    # Otherwise, use sparse DP with a dict: weight -> max value.
    states = {0: 0}
    for w, v in zip(weights, values):
        if w > capacity:
            # item cannot be taken, skip
            continue
        # iterate over a snapshot of current states
        new_states = {}
        for cur_w, cur_v in states.items():
            new_w = cur_w + w
            if new_w <= capacity:
                new_val = cur_v + v
                if new_w not in states or new_val > states.get(new_w, -1):
                    # keep the best value for this new weight
                    if new_w not in new_states or new_val > new_states[new_w]:
                        new_states[new_w] = new_val
        # merge new_states into states, keeping maximum values
        for nw, nv in new_states.items():
            if nv > states.get(nw, -1):
                states[nw] = nv
    # maximum value among all reachable weights up to capacity
    return max(states.values())"}

