def solve(weights, values, capacity):
    """Return the maximum total value obtainable with total weight <= capacity.
    Classic 0/1 knapsack using a 1‑dimensional DP array.
    """
    if capacity <= 0 or not weights:
        return 0
    dp = [0] * (capacity + 1)
    for w, v in zip(weights, values):
        if w > capacity:
            # cannot include this item
            continue
        # iterate backwards to avoid reusing the same item
        for c in range(capacity, w - 1, -1):
            new_val = dp[c - w] + v
            if new_val > dp[c]:
                dp[c] = new_val
    # The answer is the best value for any weight up to capacity.
    return max(dp)

