def solve(weights, values, capacity):
    """0/1 knapsack returning max total value with total weight <= capacity.
    Handles zero-weight items and large capacities efficiently.
    """
    if capacity <= 0 or not weights:
        return 0
    # Separate zero-weight items, they can always be taken (once each).
    zero_val = 0
    items = []
    for w, v in zip(weights, values):
        if w == 0:
            zero_val += v
        elif w <= capacity:
            items.append((w, v))
    # If no items left, return sum of zero-weight values.
    if not items:
        return zero_val
    # Choose algorithm based on capacity size.
    # Threshold chosen to avoid huge memory usage.
    THRESH = 200000  # can be tuned
    if capacity <= THRESH:
        dp = [0] * (capacity + 1)
        for w, v in items:
            for c in range(capacity, w - 1, -1):
                new = dp[c - w] + v
                if new > dp[c]:
                    dp[c] = new
        return zero_val + max(dp)
    else:
        # Sparse DP using dict: weight -> best value
        states = {0: 0}
        for w, v in items:
            new_states = {}
            for cur_w, cur_v in list(states.items()):
                nw = cur_w + w
                if nw <= capacity:
                    nv = cur_v + v
                    if nv > states.get(nw, -1):
                        if nv > new_states.get(nw, -1):
                            new_states[nw] = nv
            for nw, nv in new_states.items():
                if nv > states.get(nw, -1):
                    states[nw] = nv
        return zero_val + max(states.values())

