def solve(weights, values, capacity):
    """0/1 knapsack returning the maximum total value with total weight <= capacity.
    Uses a classic 1‑dimensional DP array when the capacity is moderate; otherwise
    falls back to a sparse dictionary DP to keep memory usage low.
    """
    if capacity <= 0 or not weights:
        return 0
    # Separate items with zero weight – they can be taken once each if they have
    # positive value. Negative‑value zero‑weight items are ignored as they would
    # only decrease the total.
    zero_val = 0
    items = []
    for w, v in zip(weights, values):
        if w == 0:
            if v > 0:
                zero_val += v
        elif w <= capacity:
            items.append((w, v))
    if not items:
        return zero_val
    # Choose algorithm based on capacity size.
    THRESH = 100000  # safe limit for list DP in typical environments
    if capacity <= THRESH:
        dp = [0] * (capacity + 1)
        for w, v in items:
            for c in range(capacity, w - 1, -1):
                new_val = dp[c - w] + v
                if new_val > dp[c]:
                    dp[c] = new_val
        return zero_val + max(dp)
    # Sparse DP for large capacities.
    states = {0: 0}
    for w, v in items:
        new_states = {}
        for cur_w, cur_v in list(states.items()):
            nw = cur_w + w
            if nw <= capacity:
                nv = cur_v + v
                if nv > states.get(nw, -1) and nv > new_states.get(nw, -1):
                    new_states[nw] = nv
        states.update(new_states)
    return zero_val + max(states.values())

