def solve(weights, values, capacity):
    """Return the maximum total value obtainable with total weight <= capacity.
    Handles zero‑weight items (they can always be taken) and chooses an algorithm
    based on the size of *capacity* to avoid excessive memory usage.
    """
    # Sum values of zero‑weight items with positive value; they can always be taken.
    zero_val = 0
    items = []
    for w, v in zip(weights, values):
        if w == 0:
            if v > 0:
                zero_val += v
        elif w <= capacity:
            items.append((w, v))
    # If capacity is zero or negative, we can only take zero‑weight items.
    if capacity <= 0:
        return zero_val
    if not items:
        return zero_val
    # Choose DP method based on capacity size.
    THRESH = 100000  # threshold for list‑based DP
    if capacity <= THRESH:
        dp = [0] * (capacity + 1)
        for w, v in items:
            for c in range(capacity, w - 1, -1):
                new_val = dp[c - w] + v
                if new_val > dp[c]:
                    dp[c] = new_val
        return zero_val + max(dp)
    else:
        # Sparse DP using a dict to keep memory low.
        states = {0: 0}
        for w, v in items:
            new_states = {}
            for cur_w, cur_v in list(states.items()):
                nw = cur_w + w
                if nw <= capacity:
                    nv = cur_v + v
                    # Keep best value for this weight.
                    if nv > states.get(nw, -1) and nv > new_states.get(nw, -1):
                        new_states[nw] = nv
            states.update(new_states)
        return zero_val + max(states.values())

def solve(n):
    """Return the number of prime numbers strictly less than n.
    Uses the Sieve of Eratosthenes with a bytearray for efficiency.
    """
    if n <= 2:
        return 0
    limit = n - 1
    sieve = bytearray(b'\x01') * (limit + 1)
    sieve[0:2] = b'\x00\x00'
    import math
    for p in range(2, int(math.isqrt(limit)) + 1):
        if sieve[p]:
            start = p * p
            step = p
            sieve[start:limit+1:step] = b'\x00' * ((limit - start) // step + 1)
    return sum(sieve)

def solve(matrix):
    """Return the determinant of an integer square matrix.
    Uses the Bareiss fraction-free Gaussian elimination algorithm for exact
    integer results. An empty matrix has determinant 1.
    """
    # Empty matrix case
    if not matrix:
        return 1
    n = len(matrix)
    # Ensure square matrix
    for row in matrix:
        if len(row) != n:
            raise ValueError("Matrix must be square")
    # Make a deep copy to avoid mutating input
    a = [list(row) for row in matrix]
    det_sign = 1
    for k in range(n-1):
        # Pivot handling: if a[k][k] == 0, find a row to swap
        if a[k][k] == 0:
            swap_row = None
            for i in range(k+1, n):
                if a[i][k] != 0:
                    swap_row = i
                    break
            if swap_row is None:
                return 0
            # swap rows k and swap_row
            a[k], a[swap_row] = a[swap_row], a[k]
            det_sign *= -1
        pivot = a[k][k]
        prev_pivot = a[k-1][k-1] if k > 0 else 1
        for i in range(k+1, n):
            for j in range(k+1, n):
                a[i][j] = (a[i][j]*pivot - a[i][k]*a[k][j]) // prev_pivot
            a[i][k] = 0  # elements below pivot become zero
    return det_sign * a[n-1][n-1]

