def solve(grid):
    """Return the number of islands in a 2‑D grid of 0/1 values.
    Islands are groups of orthogonally adjacent cells equal to 1.
    The function works for empty grids and for grids where rows may have
    different lengths (treat missing cells as water).
    """
    if not grid:
        return 0
    rows = len(grid)
    # Determine column count per row to handle ragged grids safely
    cols_per_row = [len(r) for r in grid]
    visited = [[False] * cols_per_row[i] for i in range(rows)]

    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            x, y = stack.pop()
            if visited[x][y]:
                continue
            visited[x][y] = True
            # Explore four orthogonal neighbours, checking bounds per row
            for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nx, ny = x + dx, y + dy
                if 0 <= nx < rows and 0 <= ny < cols_per_row[nx]:
                    if not visited[nx][ny] and grid[nx][ny] == 1:
                        stack.append((nx, ny))

    island_count = 0
    for i in range(rows):
        for j in range(cols_per_row[i]):
            if grid[i][j] == 1 and not visited[i][j]:
                dfs(i, j)
                island_count += 1
    return island_count

def solve(grid):
    """Count the number of islands in a binary grid.
    An island is a group of "1" cells connected horizontally or vertically.
    Parameters:
        grid (list of list of int): 2D array containing 0s and 1s.
    Returns:
        int: number of distinct islands.
    """
    if not grid:
        return 0
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    visited = [[False] * cols for _ in range(rows)]
    count = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and not visited[r][c]:
                count += 1
                # BFS/DFS to mark all cells in this island
                stack = [(r, c)]
                visited[r][c] = True
                while stack:
                    cr, cc = stack.pop()
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] == 1 and not visited[nr][nc]:
                                visited[nr][nc] = True
                                stack.append((nr, nc))
    return count

