def solve(n: int) -> int:
    """Return number of primes less than n using segmented sieve.
    Works for large n with modest memory.
    """
    if n <= 2:
        return 0
    import math
    limit = int(math.isqrt(n - 1))
    # simple sieve up to limit to get base primes
    base = bytearray(b'\x01') * (limit + 1)
    base[0:2] = b'\x00\x00'
    for p in range(2, int(math.isqrt(limit)) + 1):
        if base[p]:
            step = p
            start = p * p
            base[start:limit+1:step] = b'\x00' * ((limit - start)//step + 1)
    base_primes = [i for i in range(2, limit+1) if base[i]]
    # segmented sieve
    segment_size = max(limit, 32768)
    count = 0
    low = 2
    while low < n:
        high = min(low + segment_size, n)
        segment = bytearray(b'\x01') * (high - low)
        for p in base_primes:
            # find first multiple of p in [low, high)
            start = ((low + p - 1) // p) * p
            if start < p * p:
                start = p * p
            for multiple in range(start, high, p):
                segment[multiple - low] = 0
        # exclude 0 and 1 if they are in segment (but low>=2 so fine)
        count += sum(segment)
        low = high
    return count

