def solve(weights, values, capacity):
    """0/1 knapsack robust solution.
    Handles zero-weight items, large capacities, and avoids huge memory usage.
    """
    # Edge cases
    if capacity <= 0:
        return sum(v for w, v in zip(weights, values) if w == 0 and v > 0)
    # Add positive zero-weight values directly
    zero_val = sum(v for w, v in zip(weights, values) if w == 0 and v > 0)
    # Filter items with positive weight and weight <= capacity
    items = [(w, v) for w, v in zip(weights, values) if 0 < w <= capacity]
    if not items:
        return zero_val
    # Decide algorithm based on size
    # If capacity is moderate, use classic DP array
    if capacity <= 200000:  # adjust threshold to keep memory reasonable
        dp = [0] * (capacity + 1)
        for w, v in items:
            for c in range(capacity, w - 1, -1):
                new_val = dp[c - w] + v
                if new_val > dp[c]:
                    dp[c] = new_val
        return zero_val + max(dp)
    # Otherwise use sparse DP with pruning
    states = {0: 0}
    for w, v in items:
        new_states = {}
        for cur_w, cur_v in states.items():
            nw = cur_w + w
            if nw <= capacity:
                nv = cur_v + v
                # Keep the best value for this new weight
                if nv > states.get(nw, -1) and nv > new_states.get(nw, -1):
                    new_states[nw] = nv
        # Merge new states
        for nw, nv in new_states.items():
            if nv > states.get(nw, -1):
                states[nw] = nv
        # Prune dominated states: sort by weight and keep only increasing values
        # This keeps the map small.
        sorted_items = sorted(states.items())
        pruned = {}
        max_val = -1
        for wt, val in sorted_items:
            if val > max_val:
                pruned[wt] = val
                max_val = val
        states = pruned
    best = max(states.values()) if states else 0
    return zero_val + best

