def solve(matrix):
    """Return the determinant of an integer square matrix.
    Uses the Bareiss fraction-free Gaussian elimination algorithm for exact integer results.
    An empty matrix has determinant 1.
    """
    if not matrix:
        return 1
    n = len(matrix)
    # Verify square matrix
    for row in matrix:
        if len(row) != n:
            raise ValueError('Matrix must be square')
    # Make a deep copy to avoid mutating input
    a = [row[:] for row in matrix]
    det_sign = 1
    for k in range(n - 1):
        # Pivot if zero
        if a[k][k] == 0:
            swap = None
            for i in range(k + 1, n):
                if a[i][k] != 0:
                    swap = i
                    break
            if swap is None:
                return 0
            a[k], a[swap] = a[swap], a[k]
            det_sign = -det_sign
        pivot = a[k][k]
        prev = a[k - 1][k - 1] if k > 0 else 1
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                a[i][j] = (a[i][j] * pivot - a[i][k] * a[k][j]) // prev
            a[i][k] = 0
    return det_sign * a[n - 1][n - 1]

