def solve(s) -> bool:
    """Return True if all (), [], {} in the input are balanced.
    Non‑string inputs are treated as invalid and return False.
    """
    if not isinstance(s, str):
        return False
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    opening = set(pairs.values())
    for ch in s:
        if ch in opening:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
    return not stack

def solve(line: str):
    """Parse a CSV line into a list of fields.
    - Fields may be quoted with double quotes.
    - Inside quoted fields, commas are literal and a doubled quote "" represents a single quote.
    - Unquoted fields end at a comma.
    - Empty fields are allowed.
    - An empty input line yields [''].
    """
    if line == "":
        return [""]
    n = len(line)
    i = 0
    fields = []
    while i < n:
        if line[i] == '"':
            # quoted field
            i += 1  # skip opening quote
            field_chars = []
            while i < n:
                if line[i] == '"':
                    # escaped quote?
                    if i + 1 < n and line[i + 1] == '"':
                        field_chars.append('"')
                        i += 2
                    else:
                        i += 1  # closing quote
                        break
                else:
                    field_chars.append(line[i])
                    i += 1
            fields.append(''.join(field_chars))
            # skip following comma if present
            if i < n and line[i] == ',':
                i += 1
        else:
            # unquoted field
            start = i
            while i < n and line[i] != ',':
                i += 1
            fields.append(line[start:i])
            if i < n and line[i] == ',':
