def solve(path):
    """Simplify a Unix-style absolute path.
    - Remove '.' components.
    - Resolve '..' by removing the previous directory if any.
    - Collapse multiple slashes.
    - Ensure the result starts with '/' and has no trailing slash (except root).
    """
    parts = []
    for token in path.split('/'):
        if token == '' or token == '.':
            continue
        if token == '..':
            if parts:
                parts.pop()
        else:
            parts.append(token)
    return '/' + '/'.join(parts)

